// usePersonaWhatamiBridge (#a-session-can-ask-what-it-is) — answer `bsc persona whatami` and ACK it.
//
//   bsc persona whatami → request file → Rust watcher → `bsc://persona-whatami` → HERE → store → ack
//
// Mounted once by the shell, beside `usePersonaUseBridge`. It ALWAYS acks — a throw here would strand
// the Rust waiter until its timeout and surface as "the frontend did not answer", sending someone to
// debug the app instead of the question they asked.
import { useEffect } from "react";
import { listen } from "@tauri-apps/api/event";
import { invoke } from "@tauri-apps/api/core";
import { useAppStore } from "@/store";
import { log } from "@/shared/lib/core/log";
import { describePane, type WhatamiRequest, type WhatamiAck } from "@/app/personaWhatamiBridge";
// The titlebar's own "you are here" builder. Reused rather than re-derived, so a session is told
// EXACTLY what the user can see — two independent answers to "where am I" would eventually disagree,
// and the one the agent got would be the one nobody was looking at.
import { locationCrumb } from "@/app/chrome/locationCrumb";
// The RENDERED workspace, not the raw store field: with the legacy Console page off, a persisted
// `console` renders Glance (#3575). Reporting the raw value would tell a session the user is on a
// screen that is not on screen.
import { effectiveWorkspace } from "@/app/registry";

/**
 * Listen for `bsc://persona-whatami` and answer it.
 *
 * A thin adapter: the decision lives in `personaWhatamiBridge.ts`, unit-testable without Tauri.
 */
export function usePersonaWhatamiBridge(): void {
  useEffect(() => {
    let disposed = false;
    const un = listen<WhatamiRequest & { id: string }>("bsc://persona-whatami", (e) => {
      const { id, ...req } = e.payload;
      let ack: WhatamiAck;
      try {
        // Read off a LIVE getState rather than a captured snapshot: a persona can change mid-session
        // (that is what `bsc persona use` does), and a stale closure would answer with the old one.
        const s = () => useAppStore.getState();
        ack = describePane(id, req, {
          personaFor: (p) => s().panePersonas?.[p],
          roleFor: (p) => s().paneRoles?.[p],
          personaRecord: (pid) => s().personas?.find((x) => x.id === pid),
          // Live, like the reads above, and for a sharper reason: the user can switch tabs at any
          // point in a session, so a launch-time snapshot is wrong exactly when it matters. This is
          // why the view is answered through the round trip instead of baked into the prompt.
          view: () => {
            const st = s();
            const workspace = effectiveWorkspace(st.activeWorkspace);
            return {
              viewing: locationCrumb({ ...st, activeWorkspace: workspace }),
              workspace,
              pageTab: st.activePageTab?.[workspace],
            };
          },
        });
      } catch (err) {
        ack = { id, error: `persona whatami threw: ${err instanceof Error ? err.message : String(err)}` };
        log.error(`persona whatami ${id} threw: ${String(err)}`);
      }
      void invoke("persona_whatami_ack", { ack: { ...ack, id } }).catch((e2) => {
        log.error(`persona_whatami_ack failed for ${id}: ${String(e2)}`);
      });
    });
    return () => {
      disposed = true;
      void un.then((f) => {
        if (disposed) f();
      });
    };
  }, []);
}
